// RUN-REC-BRIDGE-001 — reconstruction minimale WF-MISTRAL-001
const input = $input.first()?.json ?? {};
const body = input.body ?? input;

function cleanString(value) {
  return typeof value === "string" ? value.trim() : "";
}

function reject(errorCode, message) {
  return [{
    json: {
      mistralStatus: "rejected",
      publicResponse: {
        ok: false,
        contractStatus: "invalid",
        source: "mistral",
        errorCode,
        message,
        answer: "",
        reason: null,
        performance: {
          promptTokens: null,
          outputTokens: null,
          totalTokens: null
        }
      }
    }
  }];
}

const client =
  body.client &&
  typeof body.client === "object" &&
  !Array.isArray(body.client)
    ? body.client
    : {};

if (client.humAuthorized !== true) {
  return reject(
    "hum_authorization_required",
    "Une autorisation HUM explicite est requise."
  );
}

if (client.requestedSource !== "mistral") {
  return reject(
    "explicit_mistral_request_required",
    "L'escalade Mistral doit être explicitement demandée."
  );
}

const previous =
  body.previousResponse &&
  typeof body.previousResponse === "object" &&
  !Array.isArray(body.previousResponse)
    ? body.previousResponse
    : {};

const previousAnswer = cleanString(previous.answer);

if (previous.source !== "slm" || !previousAnswer) {
  return reject(
    "previous_slm_response_required",
    "Une réponse SLM précédente valide est requise."
  );
}

const instruction = cleanString(body.instruction);
const selection = cleanString(body.selection);
const additionalInstruction = cleanString(body.additionalInstruction);

const page =
  body.page &&
  typeof body.page === "object" &&
  !Array.isArray(body.page)
    ? body.page
    : {};

const systemPrompt = [
  "Tu es l'étape Mistral explicitement déclenchée du BAW HUM Bridge 0.7.1.",
  "Tu produis une aide textuelle uniquement et n'exécutes aucune action externe.",
  "Réponds uniquement avec un objet JSON.",
  'Le JSON doit contenir : "ok": true, "source": "mistral", "answer": chaîne non vide, "reason": chaîne.',
  "Ne prétends pas avoir exécuté une action externe."
].join("\n");

const userPrompt = [
  `Instruction initiale : ${instruction || "(aucune)"}`,
  "",
  `Sélection : ${selection || "(aucune)"}`,
  "",
  `Réponse SLM précédente : ${previousAnswer}`,
  "",
  `Instruction additionnelle HUM : ${additionalInstruction || "(aucune)"}`,
  "",
  `Contexte de page : ${JSON.stringify(page)}`
].join("\n");

const mistralBody = JSON.stringify({
  model: "mistral-large-latest",
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: userPrompt }
  ],
  response_format: {
    type: "json_object"
  },
  temperature: 0.2,
  stream: false
});

return [{
  json: {
    mistralStatus: "ready",
    mistralBody
  }
}];

// Valide le contrat Mistral et prépare uniquement les métadonnées d'usage.
const data = $input.first()?.json ?? {};

function cleanString(value) {
  return typeof value === "string" ? value.trim() : "";
}

function toNonNegativeInt(value) {
  const n = Number(value);
  return Number.isFinite(n) && n >= 0 ? Math.trunc(n) : 0;
}

const model = cleanString(data.model) || "mistral-large-latest";
const requestId = cleanString(data.id) || null;

const promptTokens = toNonNegativeInt(data.usage?.prompt_tokens);
const completionTokens = toNonNegativeInt(data.usage?.completion_tokens);
const totalTokensFromApi = toNonNegativeInt(data.usage?.total_tokens);
const totalTokens =
  totalTokensFromApi > 0
    ? totalTokensFromApi
    : promptTokens + completionTokens;

let contractStatus = "invalid";
let publicResponse;

if (data.error) {
  const errorMessage =
    cleanString(data.error?.message) ||
    cleanString(data.message) ||
    "Échec de l'appel Mistral.";

  publicResponse = {
    ok: false,
    contractStatus: "invalid",
    source: "mistral",
    errorCode: "mistral_api_error",
    message: errorMessage,
    answer: "",
    reason: null,
    performance: {
      promptTokens,
      outputTokens: completionTokens,
      totalTokens
    }
  };
} else {
  const rawContent = cleanString(data.choices?.[0]?.message?.content);

  let parsed = null;

  if (rawContent) {
    try {
      parsed = JSON.parse(rawContent);
    } catch {
      parsed = null;
    }
  }

  const answer = cleanString(parsed?.answer);
  const reason = cleanString(parsed?.reason);

  const valid =
    parsed !== null &&
    parsed.ok === true &&
    parsed.source === "mistral" &&
    Boolean(answer) &&
    typeof parsed.reason === "string";

  if (valid) {
    contractStatus = "valid";

    publicResponse = {
      ok: true,
      contractStatus: "valid",
      source: "mistral",
      answer,
      reason,
      performance: {
        promptTokens,
        outputTokens: completionTokens,
        totalTokens
      }
    };
  } else {
    publicResponse = {
      ok: false,
      contractStatus: "invalid",
      source: "mistral",
      errorCode: "invalid_mistral_contract",
      message: "La réponse Mistral ne respecte pas le contrat attendu.",
      answer: "",
      reason: null,
      rawContent,
      performance: {
        promptTokens,
        outputTokens: completionTokens,
        totalTokens
      }
    };
  }
}

return [{
  json: {
    publicResponse,
    logRecord: {
      model,
      prompt_tokens: promptTokens,
      completion_tokens: completionTokens,
      total_tokens: totalTokens,
      contract_status: contractStatus,
      http_status: data.error ? null : 200,
      mistral_request_id: requestId
    }
  }
}];

const item = $input.first()?.json ?? {};
return [{ json: item.publicResponse ?? {
  ok: false,
  contractStatus: "invalid",
  source: "mistral",
  errorCode: "invalid_request",
  message: "Requête Mistral refusée.",
  answer: "",
  reason: null
} }];
